namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

public class Instructor
{
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
    public int CourseCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [StringLength(500)]
    public string? Notes { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", CourseCount = 4 },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", CourseCount = 3 },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", CourseCount = 3 },
            new() { Id = 4, Name = "English", Abbreviation = "ENGL", CourseCount = 2 },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, CourseCode = "CS101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented principles. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. Her research focuses on CS education and programming language design.", Email = "s.chen@university.edu" }
            },
            new()
            {
                Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithms (sorting, searching, dynamic programming). Prerequisite: CS101.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Name = "Prof. James Okafor", Title = "Professor", Bio = "Prof. Okafor is a leading researcher in algorithm design with publications in top venues including STOC and FOCS.", Email = "j.okafor@university.edu" }
            },
            new()
            {
                Id = 3, CourseCode = "CS301", Title = "Database Systems",
                Description = "Relational database design, SQL, normalization, indexing, and transaction management. Includes a semester-long project building a complete database application.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false,
                Instructor = new() { Name = "Dr. Maria Lopez", Title = "Assistant Professor", Bio = "Dr. Lopez specializes in distributed databases and data engineering. She previously worked at a major tech company on large-scale data systems.", Email = "m.lopez@university.edu" }
            },
            new()
            {
                Id = 4, CourseCode = "CS401", Title = "Machine Learning",
                Description = "Introduction to supervised and unsupervised learning, neural networks, and model evaluation. Students complete hands-on projects using Python and popular ML frameworks.",
                Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. Her research focuses on CS education and programming language design.", Email = "s.chen@university.edu" }
            },
            new()
            {
                Id = 5, CourseCode = "MATH101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Alan Turing Jr.", Title = "Professor", Bio = "Dr. Turing has taught calculus for over 20 years and authored two widely used textbooks on mathematical analysis.", Email = "a.turing@university.edu" }
            },
            new()
            {
                Id = 6, CourseCode = "MATH201", Title = "Linear Algebra",
                Description = "Vectors, matrices, linear transformations, eigenvalues, and applications. Essential for students in CS, physics, and engineering.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true,
                Instructor = new() { Name = "Dr. Priya Sharma", Title = "Associate Professor", Bio = "Dr. Sharma's research bridges pure mathematics and applied data science. She leads the interdisciplinary math modeling lab.", Email = "p.sharma@university.edu" }
            },
            new()
            {
                Id = 7, CourseCode = "MATH301", Title = "Probability and Statistics",
                Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.",
                Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Priya Sharma", Title = "Associate Professor", Bio = "Dr. Sharma's research bridges pure mathematics and applied data science. She leads the interdisciplinary math modeling lab.", Email = "p.sharma@university.edu" }
            },
            new()
            {
                Id = 8, CourseCode = "PHYS101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly lab sessions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim is an experimental physicist whose work on quantum optics has been recognized with multiple teaching excellence awards.", Email = "r.kim@university.edu" }
            },
            new()
            {
                Id = 9, CourseCode = "PHYS201", Title = "Electromagnetism",
                Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",
                Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM + Fri Lab 1:00–3:50 PM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim is an experimental physicist whose work on quantum optics has been recognized with multiple teaching excellence awards.", Email = "r.kim@university.edu" }
            },
            new()
            {
                Id = 10, CourseCode = "PHYS301", Title = "Quantum Mechanics",
                Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory. Prerequisites: PHYS201, MATH201.",
                Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true,
                Instructor = new() { Name = "Dr. Elena Vasquez", Title = "Assistant Professor", Bio = "Dr. Vasquez recently joined from a national lab where she conducted research on quantum computing hardware.", Email = "e.vasquez@university.edu" }
            },
            new()
            {
                Id = 11, CourseCode = "ENGL101", Title = "College Writing",
                Description = "Develop critical reading, analytical thinking, and clear writing skills through essay composition and peer review.",
                Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Name = "Prof. Diana Moore", Title = "Senior Lecturer", Bio = "Prof. Moore has published essays in major literary journals and is passionate about helping students find their written voice.", Email = "d.moore@university.edu" }
            },
            new()
            {
                Id = 12, CourseCode = "ENGL205", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present, examining themes of identity, freedom, and social change.",
                Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Name = "Prof. Diana Moore", Title = "Senior Lecturer", Bio = "Prof. Moore has published essays in major literary journals and is passionate about helping students find their written voice.", Email = "d.moore@university.edu" }
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

