@page "/"
@inject CourseCatalog.Services.CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-4">University Course Catalog</h1>
        <p class="lead text-muted">Explore departments, browse courses, and submit enrollment requests.</p>
        <a href="/courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
    </div>

    <section class="mb-5">
        <h2>Featured Courses</h2>
        <div class="row g-3">
            @foreach (var course in featuredCourses)
            {
                <div class="col-md-6 col-lg-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">
                                <a href="/courses/@course.Id">@course.CourseCode — @course.Title</a>
                            </h5>
                            <p class="card-text text-muted small">@course.DepartmentName · @course.Credits credits</p>
                            <p class="card-text">@Truncate(course.Description, 120)</p>
                        </div>
                        <div class="card-footer bg-transparent">
                            <small class="text-muted">@course.Instructor.Name</small>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section>
        <h2>Departments</h2>
        <div class="row g-3">
            @foreach (var dept in departments)
            {
                <div class="col-md-6 col-lg-3">
                    <div class="card h-100 text-center">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <p class="card-text text-muted">@dept.CourseCount courses</p>
                            <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-primary btn-sm">View Courses</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<CourseCatalog.Models.Course> featuredCourses = new();
    private List<CourseCatalog.Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@page "/courses"
@inject CourseCatalog.Services.CatalogService CatalogService

<PageTitle>Courses — University Course Catalog</PageTitle>

<div class="container py-4">
    <h1>Course Catalog</h1>

    <form method="get" class="row g-3 mb-4">
        <div class="col-md-6">
            <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or instructor…" />
        </div>
        <div class="col-md-4">
            <select name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @if (courses.Count == 0)
    {
        <div class="alert alert-info">No courses match your criteria. Try a different search or filter.</div>
    }
    else
    {
        <p class="text-muted">Showing @courses.Count course(s)</p>
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in courses)
                    {
                        <tr>
                            <td>@course.CourseCode</td>
                            <td><a href="/courses/@course.Id">@course.Title</a></td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.Instructor.Name</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-secondary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<CourseCatalog.Models.Course> courses = new();
    private List<CourseCatalog.Models.Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/enroll"
@inject CourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<div class="container py-4">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Submit a request to enroll in a course. You will receive confirmation via your university email.</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Your enrollment request for <strong>@selectedCourseName</strong> has been received. You'll receive a confirmation email shortly.</p>
            <hr />
            <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-8">
                <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                    <DataAnnotationsValidator />
                    <AntiforgeryToken />
                    <ValidationSummary class="text-danger" />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                        <ValidationMessage For="() => Model.FullName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., CS123456" />
                        <ValidationMessage For="() => Model.StudentId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                            <option value="0">— Select a course —</option>
                            @foreach (var course in allCourses)
                            {
                                <option value="@course.Id">@course.CourseCode — @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="notes" class="form-label">Notes (optional)</label>
                        <InputTextArea id="notes" @bind-Value="Model.Notes" class="form-control" rows="3" />
                        <ValidationMessage For="() => Model.Notes" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private CourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<CourseCatalog.Models.Course> allCourses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        allCourses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        selectedCourseName = course is not null ? $"{course.CourseCode} — {course.Title}" : "Unknown";
        submitted = true;
    }
}

